# -*- coding: utf-8 -*-
"""English translations, batch 15 (40 figures)."""
EN = {
"利甲族人": dict(lesson="Centuries of unwavering obedience",
 summary="A community that obeyed their ancestor's command and drank no wine, set up as a model.",
 witness="The Rechabites kept their ancestor Jonadab's command for generations: not to drink wine, build houses, or farm, but to live in tents. When Jeremiah was sent to test them with wine, they would not drink. God used their obedience as a contrast to rebellious Judah, promising them that they would never lack a man to stand before Him. Long holding to a received command was greatly commended by God.",
 follow=["Long and faithfully holding to the command received","Keeping the family's good tradition through the generations"],
 caution=[],
 applications=["Hold a long, undiscounted obedience to God's commands","Keep the good tradition of godly self-discipline at home","Let your obedience be a witness to those around you"],
 prayer="Lord, the Rechabites obeyed unchanged for centuries and were commended by You. Make me hold to Your commands long and undiscounted, faithfully keeping and passing on a godly tradition. Amen."),
"俄巴底（亚哈家宰）": dict(lesson="Under a wicked king, still fearing God and protecting prophets",
 summary="Ahab's steward, who feared God and hid a hundred prophets.",
 witness="Obadiah was King Ahab's steward, who 'greatly feared the LORD.' When Jezebel slaughtered the prophets, he risked his life to hide a hundred in caves, supplying them with bread and water. In the court of a wicked king, he quietly protected God's servants with his position—even in the dark, there are faithful people.",
 follow=["Still fearing God in a corrupt environment","Risking himself to protect and supply God's servants"],
 caution=["Not drifting with the tide because the environment is dark"],
 applications=["Hold to the fear of God even in an unfavorable environment","Use your position to quietly protect and supply God's workers","Trust God always keeps faithful people in the dark, and you can be one"],
 prayer="Lord, Obadiah feared You and protected prophets even in a wicked king's court. Make me hold the fear of God in a corrupt environment, quietly guarding Your servants and work with my position. Amen."),
"便哈达": dict(lesson="Arrogant taunting, God will surely answer",
 summary="King of Aram (several of the name), who fought Israel repeatedly.",
 witness="Ben-hadad was king of Aram (several of the name), who once besieged Samaria with thirty-two kings, boasting he would turn the city to dust. Yet God twice gave him into Israel's hand, showing it was not because Israel was strong, but that they might know 'the LORD is God.' To arrogant taunting, God has His own answer.",
 follow=[],
 caution=["Shaming and threatening opponents with military bluster","Repeatedly defeated yet still not knowing the God who reigns"],
 applications=["Don't threaten and suppress people with arrogant words","When threatened, look to God, not be frightened","Come to know God's sovereignty through experience"],
 prayer="Lord, Ben-hadad taunted arrogantly, yet You showed You are God. Make me not pressure people with arrogant words, look to You before threats, and know Your sovereignty more deeply through experience. Amen."),
"利汛": dict(lesson="Allying to invade, finally swallowed by a greater power",
 summary="King of Aram, who allied with Pekah to attack Ahaz.",
 witness="Rezin was king of Aram who allied with Pekah of the north to attack Judah on both sides, forcing Ahaz to turn to Assyria. As a result the Assyrian army came down, Rezin was killed, and Damascus taken captive. He who expands by invasion and alliance is finally swallowed by a greater power.",
 follow=[],
 caution=["Expanding power by alliance and invasion","Drawing on a greater power, bringing his own destruction"],
 applications=["Don't expand yourself by oppressing your neighbor","Carefully assess the consequences of risky expansion","Seek God's wisdom in international/interpersonal contests"],
 prayer="Lord, Rezin allied to invade and was finally swallowed by a greater power. Make me not expand by oppression, seeking Your wisdom in all things, walking the road of peace and justice. Amen."),
"拉伯沙基": dict(lesson="Arrogant words shaming God are finally stopped by God",
 summary="An Assyrian commander who shamed God before the walls of Jerusalem.",
 witness="The Rabshakeh was the Assyrian king's commander who, before the walls of Jerusalem, taunted loudly in the Judean dialect, shaming and blaspheming the LORD to shake the people's hearts. Hezekiah spread his words before God in prayer, and that night God struck the Assyrian army, stopping all the arrogant words.",
 follow=[],
 caution=["Shaking people's faith with threatening and blasphemous words","Putting the true God on a level with false gods, arrogant and self-exalting"],
 applications=["When you meet blaspheming and threatening words, bring them to God in prayer","Don't let arrogant words shake your faith in God","Guard your own mouth, honoring God as holy"],
 prayer="Lord, the Rabshakeh shamed You with arrogant words, and in one night You stopped him. Strengthen my faith, unshaken by threats, and guard my mouth to honor You as holy. Amen."),
"提革拉毗列色": dict(lesson="A great power is a rod God uses for a time",
 summary="King of Assyria, who plundered northern Israel.",
 witness="Tiglath-pileser was a great Assyrian emperor who swept through the nations and plundered much of northern Israel. Ahaz once paid him tribute seeking help, but invited the wolf in. Scripture shows: this power was but a rod of God's discipline—after use, the rod too is cast away.",
 follow=[],
 caution=["Conquering and plundering by force, thinking himself invincible","Becoming a scourge by which another 'invites the wolf in'"],
 applications=["Don't rely on power; remember there is a God above all kings","In crisis don't panic and 'invite the wolf in'","Look at history's rise and fall, knowing God's sovereignty"],
 prayer="Lord, Tiglath-pileser was but a rod in Your hand. Make me neither fear nor rely on power, knowing the rise and fall of nations is all under Your sovereignty. Amen."),
"撒缦以色": dict(lesson="A three-year siege confirms the consequence of breaking covenant",
 summary="King of Assyria who besieged Samaria.",
 witness="Shalmaneser was king of Assyria who, because Hoshea rebelled and turned to Egypt, besieged Samaria for three years, and the north finally fell and the people were exiled. His sword became the period at the end of God's judgment on the north's long rebellion—the consequence of breaking covenant comes sooner or later.",
 follow=[],
 caution=["Besieging by force, destroying a nation and exiling its people","Being the executor of judgment yet equally arrogant"],
 applications=["Understand that forsaking God's covenant brings consequences sooner or later","Examine your state amid 'siege'-like pressure","Turn back to God while there is still time"],
 prayer="Lord, Samaria was destroyed by Shalmaneser for breaking covenant. Make me take my relationship with You seriously, not forsaking You, turning back today, lest the consequence come. Amen."),
"撒珥根": dict(lesson="Beyond the records, God still rules",
 summary="King of Assyria who captured Ashdod.",
 witness="Sargon was a great Assyrian emperor; Isaiah records his capture of Ashdod. This king, once doubted by historians as to whether he existed, has now been confirmed by archaeology—again proving God's word is true in every detail. The overlords of nations come and go, but God's word stands forever.",
 follow=[],
 caution=["Boasting in military feats, with no regard for the Sovereign above"],
 applications=["Trust God's word as true and reliable, withstanding scrutiny","Don't be dazzled by a power's momentum; God endures longer","See God's sovereignty in the rise and fall of history"],
 prayer="Lord, the matter of Sargon confirmed Your word's truth. Strengthen my trust in Your word, seeing in the rise and fall of nations Your sovereignty that never shakes. Amen."),
"以撒哈顿": dict(lesson="Strong for a time, still in God's hand",
 summary="Sennacherib's son, king of Assyria.",
 witness="Esarhaddon was Sennacherib's son, the great Assyrian emperor who succeeded him, whose power reached its peak, even conquering Egypt. Yet however vast a power, it finally passes—the foreign peoples he resettled in Samaria later became the origin of the Samaritans, and God's history still moved on.",
 follow=[],
 caution=["Relying on his strength, thinking he could control forever","Forcibly assimilating other peoples by resettlement and mixing"],
 applications=["Don't be proud over a moment's strength","Remember even the strongest empire is in God's hand","See that God can keep advancing His plan out of a chaotic history"],
 prayer="Lord, Esarhaddon was strong for a time, still in Your hand. Make me not rely on power, but humbly know that all things and all nations are governed by You. Amen."),
"施亚雅述": dict(lesson="A name that is itself a message of hope",
 summary="Isaiah's son, his name meaning 'a remnant shall return.'",
 witness="Shear-jashub was Isaiah's son, his name meaning 'a remnant shall return.' God told Isaiah to take him to meet King Ahaz, and the child's name was itself a message to the terrified king: after judgment, God will surely keep a returning remnant. His small presence carried God's hope.",
 follow=["Carrying God's message of hope by his very existence"],
 caution=[],
 applications=["Trust that in judgment God always keeps the hope of 'a returning remnant'","Let your life too be a sign conveying hope","Hold the promise that the remnant will survive in turbulent times"],
 prayer="Lord, Shear-jashub's name declares a remnant shall return. Make me hold Your hope of keeping a remnant amid judgment and terror, that my life too be a sign conveying hope. Amen."),
"玛黑珥沙拉勒哈施罢斯": dict(lesson="The longest name in Scripture, the shortest warning",
 summary="Isaiah's son, his name meaning 'plunder hastens, spoil speeds.'",
 witness="He was Isaiah's son, his name meaning 'the spoil speeds, the plunder hastens,' the longest personal name in Scripture. God commanded the name as a warning to Judah: before this child can call his parents, the treasures of Damascus and Samaria would be plundered by Assyria. A name is itself an imminent prophecy.",
 follow=["Carrying God's warning message by his very existence"],
 caution=["(A warning) not to take lightly the imminent judgment God declares"],
 applications=["Take God's warning seriously, respond early","Understand God's prophecy will be fulfilled in its time","Let your life be a sign conveying God's message"],
 prayer="Lord, this child's name declares plunder hastens. Make me take Your warning seriously, respond early and not take it lightly, firmly trusting Your word will be fulfilled in its time. Amen."),
"米罗达巴拉但": dict(lesson="Diligent 'goodwill' can also be a temptation",
 summary="King of Babylon who sent envoys to Hezekiah.",
 witness="Merodach-baladan was king of Babylon who sent envoys to congratulate Hezekiah on recovering from illness. Flattered, Hezekiah showed them all the treasures of his storehouses. Isaiah at once prophesied: all this, along with your descendants, will be carried to Babylon. Behind diligent goodwill lay the temptation of pride.",
 follow=[],
 caution=["(A warning to Hezekiah) carried away by flattery, showing off everything","Unable to see the scheme behind diligence"],
 applications=["Facing flattery and diligence, stay sober and not show off","Don't boast to people of all God has given","Be especially careful and self-guarded in good times (recovery)"],
 prayer="Lord, Hezekiah showed off because of Merodach-baladan's goodwill, and brought on a prophecy. Make me stay humble and vigilant amid flattery and good times, not boasting of what You have given. Amen."),
"以赛亚的妻子": dict(lesson="Bearing the prophetic mission with her husband",
 summary="Called a prophetess, who bore Isaiah a son.",
 witness="Isaiah's wife is called 'the prophetess,' and bore Isaiah a son whose very name was a prophecy (Maher-shalal-hash-baz). She was not only a prophet's family member, but bore the mission of conveying God's message with her husband—even the child's existence became a sign to the people.",
 follow=["Of one heart with her spouse, bearing the spiritual mission together","Letting the family too be a vessel conveying God's message"],
 caution=[],
 applications=["Serve of one heart with your spouse, bearing the mission together","Let your family (including children) be a witness","Value husband and wife co-laboring in service"],
 prayer="Lord, Isaiah's wife bore the mission with him. Make me of one heart with my spouse, that our family together be a vessel conveying Your message and witnessing for You. Amen."),
"西莱雅": dict(lesson="Faithfully conveying, carrying the prophecy to its end",
 summary="Son of Neriah, Baruch's brother, sent to carry the book of prophecy to Babylon.",
 witness="Seraiah was the son of Neriah, Baruch's brother. Jeremiah wrote all the disaster about Babylon in a book and gave it to Seraiah, telling him to read it aloud when he reached Babylon, then bind a stone to it and throw it into the Euphrates, symbolizing that Babylon would so sink and rise no more. He faithfully carried God's prophecy to where it should go, doing the sign he should do.",
 follow=["Faithfully conveying and executing the word of God entrusted","Confirming God's message by action (a sign)"],
 caution=[],
 applications=["Faithfully complete the message God entrusts you to convey","Match the truth you believe with concrete action","Trust God's word will be fulfilled as the prophecy decreed"],
 prayer="Lord, Seraiah faithfully carried the prophecy to Babylon and did the sign. Make me faithfully convey and execute the word You entrust, confirming the truth I believe with action. Amen."),
"示玛雅（尼希兰人）": dict(lesson="A counterfeit prophet, bringing God's accounting on himself",
 summary="A false prophet who wrote from Babylon attacking Jeremiah.",
 witness="Shemaiah was a false prophet in exile who wrote from Babylon back to Jerusalem, urging the priests to suppress Jeremiah and put him in stocks. Jeremiah declared: God will surely call him to account, and his descendants will not see the good God will give. Whoever acts on his own will in God's name, God will call to account.",
 follow=[],
 caution=["Speaking his own words in God's name","Using office to suppress the true conveyor of God's word"],
 applications=["Don't push your own intentions under spiritual authority","Respect and protect those faithfully conveying truth","Hold a trembling, reverent heart in spiritual matters"],
 prayer="Lord, Shemaiah counterfeited a prophet to suppress Jeremiah, and brought accounting on himself. Make me not act on my own will in Your name, humbly receiving truth, not suppressing those You send. Amen."),
"约哈难（加利亚之子）": dict(lesson="A good start without a good end, in the end unwilling to listen",
 summary="A commander after Judah's fall, who led the people down to Egypt.",
 witness="Johanan was a commander after Judah's fall, who faithfully pursued Ishmael, the assassin of the governor, and rescued the captive remnant, and at first came to inquire of Jeremiah. Yet when God's word did not suit him (to stay in the land and not go to Egypt), he refused to obey, and insisted on leading everyone down to Egypt. Inquiring of God yet only wanting to hear what he wished, in the end disobedient.",
 follow=["Bearing responsibility to protect the remnant and pursue the murderer","Willing to come and inquire God's will"],
 caution=["Inquiring of God, yet accepting only the answer that suited him","Insisting on his own way despite knowing God's command"],
 applications=["When inquiring of God, be ready to accept an answer not to your liking","Don't 'ask but not listen'; truly obey","In major decisions take God's word as the standard, not your own calculation"],
 prayer="Lord, Johanan inquired of You yet would not heed Your word. Make me inquire of You with a truly obedient heart, willing to accept an answer not to my liking, and truly act on Your word. Amen."),
"以实玛利（尼探雅之子）": dict(lesson="Royal blood reduced to a murderer's hand",
 summary="A royal descendant who assassinated the governor Gedaliah.",
 witness="Ishmael was a royal descendant who, instigated by the king of Ammon, feigned coming to Governor Gedaliah's feast and at table killed him and those with him, and carried off the remnant. Noble birth did not stop his viciousness—blood cannot guarantee character.",
 follow=[],
 caution=["Seizing power and venting fury by deceit and violence","Instigated by an outside force, harming his own compatriots"],
 applications=["Don't make birth and status capital for doing evil","Refuse to be used by others to harm people","Treat people with honesty, not a knife hidden behind a smile at the feast"],
 prayer="Lord, Ishmael of royal blood committed the evil of assassination. Cleanse my heart, that I not make birth capital for evil, nor be used to harm people, treating people with honesty. Amen."),
"尼布撒拉旦": dict(lesson="The one who destroyed the city yet treated the prophet well",
 summary="The captain of Babylon's guard, who burned Jerusalem.",
 witness="Nebuzaradan was the captain of Babylon's guard, commanded to burn Jerusalem, the temple, and the palace, and to carry off the people. Yet to Jeremiah he, by the king's order, treated him well, giving him freedom, letting him choose to stay or go, and providing food. The hand executing judgment also, by God's arrangement, protected God's servant.",
 follow=["Still treating well those who should be treated well, within his duty"],
 caution=["(Background) he was an instrument executing God's judgment; the judgment was real"],
 applications=["Even bearing a 'demolishing' duty, keep a heart that treats people well","Trust God can preserve whom He would preserve amid judgment","See God's sovereignty using even an enemy's hand"],
 prayer="Lord, Nebuzaradan destroyed the city yet treated Jeremiah well. Make me keep a kind heart in my duty, and let me see Your sovereignty, that even the hand of judgment is in Your control. Amen."),
"尼布沙斯班": dict(lesson="A line in the record, witnessing fulfillment",
 summary="An official of Babylon.",
 witness="Nebushazban was one of Babylon's officials at the fall of Jerusalem, his name recorded with his colleagues on the day the city fell. These foreign officials' names became a historical footnote to the fulfillment that 'Jerusalem was taken according to God's word.' God's word does not fail even in detail.",
 follow=[],
 caution=["(Background) Jerusalem's fall was the consequence of rebellion"],
 applications=["Fear the truth of God's word, fulfilled even in detail","See traces of God's sovereignty in the details of history","Take God's warning seriously, harbor no false hope"],
 prayer="Lord, Nebushazban's name became a footnote to Your word's fulfillment. Make me fear the truth of Your word, seriously respond to Your warning, harbor no false hope. Amen."),
"尼甲沙利薛": dict(lesson="The dignitary seated at the city gate too is in God's hand",
 summary="An official of Babylon.",
 witness="Nergal-sharezer was a high Babylonian official who, after the city fell, sat 'in the middle gate' with the other officials—holding the power of judgment. These dignitaries, illustrious for a time, were but instruments God used to accomplish judgment; however great their power, they were still in the hand of the true Ruler.",
 follow=[],
 caution=["Thinking that sitting at 'the middle gate of power' he could rule forever"],
 applications=["Not dazzled by an illustrious position; God is above it","Remember human authority is all borrowed and limited","Before the powerful still fear the One who truly reigns"],
 prayer="Lord, Nergal-sharezer sat at the middle gate of power, yet was still an instrument in Your hand. Make me not dazzled by power, but fear You who truly reign forever. Amen."),
"布西": dict(lesson="Passing the root of faith to the next generation",
 summary="Ezekiel's father, a priest.",
 witness="Buzi was the father of the prophet Ezekiel, a priest. Scripture records only his name, but it was this priestly home that raised Ezekiel, who faithfully conveyed God's word even in exile. Fathers who quietly pass on faith are often the root of the next generation's spiritual life.",
 follow=["Quietly passing the root of faith in the family","Influencing the next generation by his identity and office"],
 caution=["Not neglecting the nurture of children's spiritual life"],
 applications=["Value passing faith to children and juniors","In ordinariness, be the root of the next generation's spiritual life","Trust the family's spiritual inheritance is remembered by God"],
 prayer="Lord, Buzi's priestly home raised Ezekiel. Make me faithfully pass the root of faith to the next generation, rooting their spiritual life in ordinariness. Amen."),
"亚施毗拿": dict(lesson="A high-ranking eunuch treating people with goodwill",
 summary="The chief eunuch of Babylon who managed Daniel and others.",
 witness="Ashpenaz was the chief eunuch of the king of Babylon, commanded to select Daniel and the other youths for training. When Daniel asked him to allow them not to eat the king's food, though he had misgivings (fearing the king would see them looking poorly), he treated them with goodwill and quietly permitted the test. A foreign official's consideration left room for Daniel's loyalty.",
 follow=["Treating people with goodwill and flexibility within his authority","Considerate of others' difficulties and convictions"],
 caution=["Within goodwill, still balancing the soundness of duty"],
 applications=["In a managing post, treat subordinates' difficulties with goodwill","Leave room for others to hold their principles","Seek wisdom that balances system and human consideration"],
 prayer="Lord, Ashpenaz treated Daniel with goodwill, leaving room for his loyalty. Make me treat people with goodwill in my authority, leaving room for others to hold their principles. Amen."),
"亚略": dict(lesson="Carrying out orders, yet able to keep some compassion",
 summary="The captain of the king of Babylon's guard.",
 witness="Arioch was the captain of the king of Babylon's guard, ordered to kill all the wise men of Babylon (including Daniel). Daniel sought him with 'prudent and discreet' words for a delay, and he let Daniel go in to the king to ask for time. The executor bearing the king's command still, in the gap, gave the wise man a thread of life.",
 follow=["Still keeping some compassion in carrying out his duties","Giving people reasonable room to appeal and maneuver"],
 caution=[],
 applications=["When enforcing rules, also leave a thread of room for people","Treat those in hard situations with consideration","Seek wisdom between duty and human feeling"],
 prayer="Lord, Arioch carried out his orders yet gave Daniel room to maneuver. Make me keep compassion in my duty, leaving a thread of life for people. Amen."),
"大利乌（玛代人）": dict(lesson="Honoring God's servant above the schemes of officials",
 summary="Who held power after Belshazzar, threw Daniel into the lions' den, and rescued him.",
 witness="Darius the Mede fell into the trap of his officials and was forced to throw Daniel into the lions' den, yet fasted and could not sleep all night. At daybreak he ran to call out, and seeing Daniel preserved by God, he decreed the whole kingdom should fear Daniel's God. Though weak for a moment, in the end he stood on God's side.",
 follow=["Honoring those who faithfully serve God","Seeing God's work, leading the people to fear God"],
 caution=["Compromising for a moment, enacting an evil law out of vanity and fear of his officials"],
 applications=["Don't make decisions against your conscience and harmful to others for vanity or others' words","Provide support for the faithful who love the Lord around you","Seeing God's work, lead others to fear Him together"],
 prayer="Lord, Darius, though weak for a moment, finally honored Daniel and his God. Make me not compromise for vanity, honor the faithful who love You, and lead people to fear You. Amen."),
"耶斯列（何西阿之子）": dict(lesson="Judgment in a name, yet hope hidden within",
 summary="Hosea's firstborn, a name symbolizing judgment.",
 witness="Jezreel was the firstborn of the prophet Hosea, the name commanded by God as a sign of judgment on the house of Jehu for shedding blood and on the north. Yet 'Jezreel' originally means 'God sows'—in the name of judgment, God also planted the hope of replanting and revival.",
 follow=["Obeying God even when the charge carries a hard-to-grasp meaning"],
 caution=["(A warning in the background) the house of Jehu's wanton bloodshed invited judgment"],
 applications=["Trust God has a deeper arrangement amid hard-to-grasp situations","See that even God's discipline hides the hope of revival","Obey the role God entrusts, even when not understood"],
 prayer="Lord, Jezreel's name is both judgment and the hope of 'God sows.' Make me see Your heart to sow and revive amid discipline, obeying Your arrangement. Amen."),
"罗路哈玛": dict(lesson="The name 'no mercy' hides the promise of mercy",
 summary="Hosea's daughter, the name meaning 'no mercy.'",
 witness="Lo-ruhamah was the daughter of the prophet Hosea, the name meaning 'no mercy,' a sign of God's judgment on rebellious Israel. Yet God immediately promised: a turning would come, and 'the unpitied' would receive mercy again. In the name of judgment is buried the hope of restoration.",
 follow=["Still holding the hope that mercy will surely come, amid the sign of judgment"],
 caution=["(A warning) rebellion brought one for a time to 'no mercy'"],
 applications=["Look to God's restoring mercy amid discipline","Trust God's judgment hides the promise of restoration","Pray for the return of those once 'unpitied'"],
 prayer="Lord, Lo-ruhamah's name declares judgment, yet You promised mercy would come. Make me look to Your restoring mercy amid discipline, and pray for the return of those far from You. Amen."),
"罗阿米": dict(lesson="After 'not My people' comes the promise of 'My people'",
 summary="Hosea's son, the name meaning 'not My people.'",
 witness="Lo-ammi was the son of Hosea, the name meaning 'not My people,' declaring the severing of God's relationship with rebellious Israel. Yet God immediately promised: in the very place where it was said to them 'you are not My people,' it would be said 'you are sons of the living God.' In the deepest severance, God prepared the deepest acceptance.",
 follow=["Holding the hope of restoration that they 'will again be called God's people'"],
 caution=["(A warning) rebellion brought one for a time to 'not My people'"],
 applications=["Look to God's promise of restoration amid relational estrangement","Trust God can receive 'not My people' again as children","Pray for the return of those estranged from God"],
 prayer="Lord, Lo-ammi's name declares 'not My people,' yet You promised they would be called sons of God. Make me firmly trust Your restoring love, and pray for the return of those estranged from You. Amen."),
"亚米太": dict(lesson="A prophet's father, his name kept at the source",
 summary="Jonah's father.",
 witness="Amittai was the father of the prophet Jonah, a man of Gath-hepher. Scripture records his name as the source of Jonah's identity. An unremarkable father raised the prophet God sent to Nineveh—and though Jonah's obedience was up and down, his root was still in this home.",
 follow=["Quietly being the root of the next generation's calling"],
 caution=[],
 applications=["Value the responsibility of raising the next generation's called ones","Be faithful in inconspicuous places, with possibly far-reaching influence","Pray for your children's future calling"],
 prayer="Lord, Amittai raised the prophet Jonah. Make me faithful in inconspicuous places, the root of the next generation's called ones, praying for their future calling to serve You. Amen."),
"比利家": dict(lesson="A prophet's father, a link between generations",
 summary="The father of the prophet Zechariah.",
 witness="Berechiah was the father of the prophet Zechariah and the son of Iddo, living in the age of return and rebuilding. He himself has little record, yet was a link connecting a prophetic family line, raising Zechariah who encouraged the people to build the temple. The generation that links forward and back is also in God's plan.",
 follow=["Faithfully linking forward and back between the generations"],
 caution=[],
 applications=["Value your position of inheritance in the faith's generations","Faithfully pass what you've received to the next generation","Trust the linking generation is also remembered by God"],
 prayer="Lord, Berechiah carried on a prophetic family line and raised Zechariah. Make me faithfully link forward and back, passing the faith I've received to the next generation. Amen."),
"易多": dict(lesson="Spiritual influence bears fruit across generations",
 summary="The grandfather of the prophet Zechariah.",
 witness="Iddo was the grandfather of the prophet Zechariah, also recorded as a prophet/seer. Two or three generations later, his family raised up Zechariah, an important prophet of the return period. Spiritual influence often ferments across generations—today's faithfulness will bear fruit in descendants.",
 follow=["By today's faithfulness, storing up a spiritual inheritance for descendants","Valuing cross-generational spiritual influence"],
 caution=["Not despising the long-term value of your faithfulness today"],
 applications=["Trust your faith today will affect descendants","Pray for and store up blessing for descendants' spiritual life","Walk this generation well, passing the baton on"],
 prayer="Lord, Iddo's faithfulness bore fruit in Zechariah generations later. Make me faithfully love You today, storing a spiritual inheritance for descendants, affecting a future I cannot see. Amen."),
"设巴萨": dict(lesson="Returning with the holy vessels, restarting worship",
 summary="A return leader appointed governor of Judah, who brought back the temple vessels.",
 witness="Sheshbazzar was an early leader of the return; Cyrus handed over to him the gold and silver vessels plundered from the temple, to bring back to Jerusalem, and laid the foundation of the temple. He quietly took up the first leg of 'return and rebuilding,' so interrupted worship could restart.",
 follow=["Faithfully taking up the responsibility of return and rebuilding","Valuing bringing the 'holy vessels' (sacred charge) back on track"],
 caution=["The road of rebuilding is long; perseverance without discouragement is needed"],
 applications=["After desolation, be the one who restarts","Faithfully keep and return a sacred charge","Offer your part for spiritual 'rebuilding'"],
 prayer="Lord, Sheshbazzar returned with the holy vessels and restarted worship. Make me, after desolation and interruption, faithfully take up the rebuilding, bringing worship back on track. Amen."),
"约萨达": dict(lesson="In exile, keeping the priestly line alive",
 summary="The father of the high priest Jeshua.",
 witness="Jozadak was a priest carried to Babylon, who did not himself return, but fathered Jeshua, the high priest after the return. Nation broken, temple destroyed, exiled in a foreign land, yet the priestly line was not cut off—he kept the inheritance alive in the dark, so revival had someone to take the baton.",
 follow=["Holding faith and identity amid affliction and displacement","Keeping the spiritual inheritance for the next generation"],
 caution=["Not giving up the priestly tradition received because of hard circumstances"],
 applications=["Hold faith in displaced, unfavorable environments","Even if you don't see fruit yourself, keep it for the next generation","Trust God will carry on and use the inheritance you keep"],
 prayer="Lord, Jozadak kept the priestly line alive in exile and raised Jeshua. Make me hold faith in hardship, keeping the spiritual inheritance for the next generation. Amen."),
"哈拿尼（尼希米之兄）": dict(lesson="One truthful report ignites a rebuilding",
 summary="Nehemiah's brother, sent to govern Jerusalem.",
 witness="Hanani was Nehemiah's brother who came from Judah and truthfully reported the state of Jerusalem—the wall broken down, the gates burned with fire, the remnant in great distress. It was this truthful report that pierced and ignited Nehemiah's resolve to return and rebuild. One faithful word can open a revival.",
 follow=["Truthfully reporting what he saw, without glossing","Inspiring action with a real burden"],
 caution=["Not reporting only good and hiding the real need"],
 applications=["Truthfully reflect the need and state you see","Inspire those who should act with a real burden","Don't paper over with false peace; let truth bring change"],
 prayer="Lord, Hanani's truthful report ignited Nehemiah's resolve to rebuild. Make me one who tells the truth, inspiring change with a real burden, not glossing or evading. Amen."),
"示玛雅（阻挠尼希米）": dict(lesson="Hired 'spiritual advice' must be discerned",
 summary="A false prophet hired to intimidate Nehemiah.",
 witness="This Shemaiah was bought off by Tobiah and Sanballat, feigning a warning for Nehemiah to hide in the temple for safety, hoping to lead him to break the rules and ruin his name. But Nehemiah discerned that 'God had not sent him' and refused to fall for it. Advice wrapped in a spiritual cloak also needs to be tested for truth.",
 follow=[],
 caution=["Bought off, leading people astray with 'spiritual advice'","Manipulating others with intimidation and alarmism"],
 applications=["Keep discernment toward advice wrapped in a spiritual cloak","When intimidated don't panic; first seek God's will","Don't be bought to harm others' ministry and name"],
 prayer="Lord, Nehemiah saw through Shemaiah's hired scheme. Give me a discerning spirit, not deceived by intimidation and advice in a spiritual cloak, walking steadily in Your will. Amen."),
"挪亚底": dict(lesson="A prophetess's office, used in the wrong place",
 summary="A prophetess who intimidated Nehemiah.",
 witness="Noadiah was a prophetess who, with a band of false prophets, was hired to make Nehemiah afraid and to make him sin. She had the office of 'prophet,' yet stood on the side hindering God's work. A spiritual gift and office, if not submitted to God, instead become a hindrance.",
 follow=[],
 caution=["Using a spiritual office to do things that hinder God's work","Hired to intimidate and shake those who do good"],
 applications=["Don't use a spiritual identity to hinder others doing God's work","Often examine whether you stand on the side of advancing or hindering","Refuse to be bought to intimidate and shake people"],
 prayer="Lord, Noadiah hindered Nehemiah in the name of a prophet. Make me use spiritual gifts to advance Your work, not to hinder; often examining which side I am on. Amen."),
"哈拿尼雅（尼希米治理者）": dict(lesson="Faithful and God-fearing, fit to be entrusted",
 summary="Faithful and fearing God, appointed to govern the citadel of Jerusalem.",
 witness="Hananiah was the one Nehemiah appointed to manage the citadel of Jerusalem, because he was 'a faithful man and feared God more than many.' In choosing people, Nehemiah looked not at relationship, but at faithfulness and fear. These two made him fit for a heavy charge.",
 follow=["Winning trust by faithfulness and the fear of God","Dutiful and reliable in the post entrusted"],
 caution=[],
 applications=["Let 'faithful, God-fearing' be the foundation of being trusted","Be a reliable, trustworthy person in your post","In choosing and using people, value faithfulness and fear of God too"],
 prayer="Lord, Hananiah was entrusted with a heavy charge because of faithfulness and fear. Make me a faithful, God-fearing person, reliable and dutiful in the post entrusted. Amen."),
"细利斯": dict(lesson="The wife who offered a vicious scheme also sensed the downfall",
 summary="Haman's wife, who advised building a gallows to harm Mordecai.",
 witness="Zeresh was Haman's wife. When Haman raged against Mordecai, it was she and his friends who advised: build a gallows fifty cubits high and hang Mordecai on it. Yet when Haman began to decline, she changed her tune: you will surely fall before Mordecai. She both abetted evil and foresaw the downfall with the wind.",
 follow=[],
 caution=["Advising her relative, but it was a vicious scheme to harm","Helping evil when there was gain, withdrawing when the tide turned"],
 applications=["Don't give loved ones a 'harmful' idea","Be a voice for good, not for abetting evil, in the family","Don't be one who bends with the wind, only self-protecting"],
 prayer="Lord, Zeresh gave Haman a vicious scheme. Make me a voice for good in my home, not abetting people in evil, nor bending with the wind for self-protection. Amen."),
"哈曼十子": dict(lesson="The inheritance of evil, perishing together",
 summary="Haman's ten sons, who perished with their father.",
 witness="Haman's ten sons inherited their father's hatred of the Jews, and in that counterattack were all destroyed, their ten names listed together. The road of hatred their father walked, the sons walked to its end together. When sin and hatred are passed down in a family, the result is an end the whole family bears together.",
 follow=[],
 caution=["Inheriting the father's hatred and evil deeds","The whole family walking the road of rebellion, bearing its result together"],
 applications=["Don't let hatred and evil pass down generation by generation in the family","Be the one who breaks the cycle of sin in the family","Watch and pray for the family's spiritual direction"],
 prayer="Lord, Haman's ten sons inherited their father's hatred and perished together. Help me cut off the inheritance of hatred and evil in the family, be the one who breaks the cycle, leading the family toward Your blessing. Amen."),
"希该": dict(lesson="Treating a charge well, helping another be shown grace",
 summary="The eunuch in charge of the harem women, who treated Esther well.",
 witness="Hegai was the eunuch in charge of the harem women. When Esther was brought to the palace, Hegai 'was pleased with her and showed her favor,' quickly giving her the cosmetics, portion of food, and seven maids, and placing her in the best quarters. His goodwill within his authority quietly advanced Esther, who would later save the Jews.",
 follow=["Treating well those entrusted within his authority","Helping another be blessed by showing grace"],
 caution=[],
 applications=["Treat well those who fall under your care","Use your position to advance another's good","Trust God can greatly use one small act of grace"],
 prayer="Lord, Hegai showed Esther grace, quietly advancing the deliverance. Make me treat well those I care for, using my position to advance another's blessing. Amen."),
"沙甲": dict(lesson="A nameless steward who did his duty",
 summary="The eunuch in charge of the concubines.",
 witness="Shaashgaz was the eunuch in charge of the concubines, mentioned in Esther only by name and office. In the vast system of the Persian court, he quietly did his part. Scripture records his name, reminding us: God sees every small role in a system that does its duty.",
 follow=["Quietly doing his duty in a vast system"],
 caution=[],
 applications=["Be faithful in your part in a large organization or system","Don't despise the dutifulness of a 'small role'","Trust God sees everyone who quietly does their duty"],
 prayer="Lord, Shaashgaz quietly did his duty in the court system. Make me faithful in my part in the system I am in, knowing You see every small role that does its duty. Amen."),
}
